package com.jestk.browser.engine

import androidx.webkit.UserAgentMetadata
import androidx.webkit.UserAgentMetadata.BrandVersion

/**
 * Aligns User-Agent Client Hints metadata ([UserAgentMetadata]) for Android WebView,
 * mirroring the approach used by DuckDuckGo Android.
 *
 * Rather than generating synthetic brand lists or guessing GREASE brands/versions,
 * this provider inspects the native [UserAgentMetadata] initialized by the Chromium engine
 * on the [android.webkit.WebSettings], preserves the authentic GREASE brand and versions generated by
 * Chromium, and replaces any "Android WebView" branding with "Google Chrome".
 */
object UserAgentMetadataProvider {

    const val DEFAULT_CHROME_MAJOR_VERSION = "130"
    const val DEFAULT_PLATFORM_VERSION = "10.0.0"
    const val BRAND_CHROMIUM = "Chromium"
    const val BRAND_GOOGLE_CHROME = "Google Chrome"
    const val BRAND_ANDROID_WEBVIEW = "Android WebView"

    private val CHROME_VERSION_PATTERN = Regex("""\bChrome/([0-9]+)(?:\.([0-9]+(?:\.[0-9]+)*))?""", RegexOption.IGNORE_CASE)
    private val ANDROID_VERSION_PATTERN = Regex("""\bAndroid\s+([0-9]+(?:\.[0-9]+)*)""", RegexOption.IGNORE_CASE)

    fun extractChromeMajorVersion(userAgent: String?): String {
        if (userAgent.isNullOrBlank()) return DEFAULT_CHROME_MAJOR_VERSION
        val match = CHROME_VERSION_PATTERN.find(userAgent) ?: return DEFAULT_CHROME_MAJOR_VERSION
        return match.groupValues[1]
    }

    fun extractChromeFullVersion(userAgent: String?): String {
        if (userAgent.isNullOrBlank()) return "$DEFAULT_CHROME_MAJOR_VERSION.0.0.0"
        val match = CHROME_VERSION_PATTERN.find(userAgent) ?: return "$DEFAULT_CHROME_MAJOR_VERSION.0.0.0"
        val full = match.value.substringAfter('/')
        return if (full.contains('.')) full else "$full.0.0.0"
    }

    fun extractPlatformVersion(userAgent: String?): String {
        if (userAgent.isNullOrBlank()) return DEFAULT_PLATFORM_VERSION
        val match = ANDROID_VERSION_PATTERN.find(userAgent) ?: return DEFAULT_PLATFORM_VERSION
        val ver = match.groupValues[1]
        return normalizePlatformVersion(ver)
    }

    private fun normalizePlatformVersion(ver: String): String {
        val dotCount = ver.count { it == '.' }
        return when (dotCount) {
            0 -> "$ver.0.0"
            1 -> "$ver.0"
            else -> ver
        }
    }

    /**
     * Builds updated metadata from an existing [currentMetadata] if available (the DuckDuckGo pattern),
     * or constructs a default fallback metadata instance when [currentMetadata] is null or has an empty brand list.
     */
    fun buildOrUpdateMetadata(
        currentMetadata: UserAgentMetadata?,
        userAgent: String?,
        rawUserAgent: String? = null
    ): UserAgentMetadata {
        if (currentMetadata != null && currentMetadata.brandVersionList.isNotEmpty()) {
            val finalBrandList = currentMetadata.brandVersionList.map { item ->
                if (item.brand.contains(BRAND_ANDROID_WEBVIEW, ignoreCase = true) || item.brand.contains("WebView", ignoreCase = true)) {
                    BrandVersion.Builder()
                        .setBrand(BRAND_GOOGLE_CHROME)
                        .setMajorVersion(item.majorVersion)
                        .setFullVersion(item.fullVersion)
                        .build()
                } else {
                    item
                }
            }

            return UserAgentMetadata.Builder()
                .setPlatform(currentMetadata.platform)
                .setPlatformVersion(currentMetadata.platformVersion)
                .setFullVersion(currentMetadata.fullVersion)
                .setModel(currentMetadata.model)
                .setBitness(currentMetadata.bitness)
                .setArchitecture(currentMetadata.architecture)
                .setWow64(currentMetadata.isWow64)
                .setMobile(currentMetadata.isMobile)
                .setBrandVersionList(finalBrandList)
                .build()
        }

        return buildFallbackMetadata(userAgent, rawUserAgent)
    }

    /**
     * Fallback metadata builder when native metadata is unavailable (e.g. Robolectric unit tests).
     */
    fun buildFallbackMetadata(
        userAgent: String?,
        rawUserAgent: String? = null,
        deviceModel: String = "",
        osRelease: String = ""
    ): UserAgentMetadata {
        val effectiveUaForFull = rawUserAgent ?: userAgent
        val majorVersion = extractChromeMajorVersion(userAgent)
        val fullVersion = extractChromeFullVersion(effectiveUaForFull)
        val platformVersion = if (osRelease.isNotBlank()) {
            normalizePlatformVersion(osRelease)
        } else {
            extractPlatformVersion(userAgent)
        }

        val brandList = listOf(
            BrandVersion.Builder()
                .setBrand("Not(A:Brand)")
                .setMajorVersion("99")
                .setFullVersion("99.0.0.0")
                .build(),
            BrandVersion.Builder()
                .setBrand(BRAND_CHROMIUM)
                .setMajorVersion(majorVersion)
                .setFullVersion(fullVersion)
                .build(),
            BrandVersion.Builder()
                .setBrand(BRAND_GOOGLE_CHROME)
                .setMajorVersion(majorVersion)
                .setFullVersion(fullVersion)
                .build()
        )

        return UserAgentMetadata.Builder()
            .setBrandVersionList(brandList)
            .setFullVersion(fullVersion)
            .setPlatform("Android")
            .setPlatformVersion(platformVersion)
            .setArchitecture("")
            .setBitness(64)
            .setModel(deviceModel)
            .setMobile(true)
            .build()
    }

    fun buildMetadata(
        userAgent: String?,
        rawUserAgent: String? = null,
        deviceModel: String = "",
        osRelease: String = ""
    ): UserAgentMetadata = buildFallbackMetadata(userAgent, rawUserAgent, deviceModel, osRelease)
}
